import React, {useState} from 'react'
import Header from '../components/Header'
import {Container, Row, Col, Form, Button} from 'react-bootstrap'
import background from '../images/guest_screen.webp'
import List_trains from '../components/List_trains'
import api_response from '../train_between_stations_response.json'

function GuestScreen() {
  const[show, setShow]=useState(false)
  const [source, setSource] =useState('')
  const [destination, setDestination] =useState('')
  const [date, setDate] =useState('')
  const [data, setData]=useState({})
  
  const submitHandler= async (e) => {
    e.preventDefault()
    try {
      const fetchedData = await fetchData(url, options);
      setData(fetchedData);
      console.log(data)
    } catch (error) {
      console.error('Error fetching data:', error);
    }
    setData(api_response)
    setShow(true)
    console.log(data)
  }

  
  const handleDestinationChange = (e) => {
    setDestination(e.target.value)
  }

  const handleSourceChange = (e) => {
    setSource(e.target.value)
  }

  const handleDateChange = (e) => {
    setDate(dateFormatter((e.target.value)))
  }

  const dateFormatter = (d) => {
    const [a,b,c] = d.split()
    return `{c}-{b}-{a}`
  }

  const url = `https://irctc1.p.rapidapi.com/api/v3/trainBetweenStations?fromStationCode=${source}&toStationCode=${destination}&dateOfJourney=${date}`;
  const options = {
	  method: 'GET',
	  headers: {
		  'x-rapidapi-key': '6cd4d36a20msh6ddd329bbe28acep13ce1bjsnac28921093ef',
		  'x-rapidapi-host': 'irctc1.p.rapidapi.com'
	  }
  };

  const fetchData = async (url, options) => {
    try {
        const response = await fetch(url, options);
        const result = await response.text();
        return result;
    } catch (error) {
        throw error;
    }
  };

  return (
    <div style={{backgroundColor: '#3C413E'}}>
      <Container fluid>
        <Row>
          <Header />
          <Col md={12} style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center',        backgroundSize: 'cover', height: '100vh', opacity: 0.7}}>
          
          <Form onSubmit={submitHandler} className='d-flex bold mt-4' style={{marginLeft: 100}}>

            <Form.Group className="mb-3 me-4" controlId="source">
              <Form.Label className='fw-bold fs-4'>Source</Form.Label>
              <Form.Control type="text" placeholder="Enter Source" value={source} onChange={handleSourceChange} />
            </Form.Group>

            <Form.Group className="mb-3 me-4" controlId="destination">
              <Form.Label className='fw-bold fs-4'>Destination</Form.Label>
              <Form.Control type="text" placeholder="Enter Destination" value={destination} onChange={handleDestinationChange} />
            </Form.Group>

            <Form.Group className="mb-3 me-4" controlId="date">
              <Form.Label className='fw-bold fs-4'>Select Date</Form.Label>
              <Form.Control type="date" value={date} onChange={handleDateChange} />
            </Form.Group>

            <Button variant="primary" type="submit" style={{height: '35px', marginTop: 45}}>
              Submit
            </Button>
          </Form>

          </Col>
        </Row>
        <Row>
          <Col md={12}>
            
          </Col>
        </Row>
      </Container>
    </div>
  )
}

export default GuestScreen
